import type {QueueInfo} from '../types';

export const filterQueues = <TQueues extends Array<QueueInfo> | undefined>(
    queues?: TQueues,
    hideQueues?: ReadonlySet<string>,
): QueueInfo[] => {
    if (queues === undefined) {
        return [];
    }

    if (hideQueues === undefined) {
        return queues;
    }

    return queues.filter((queue) => !hideQueues.has(queue.key));
};
